mapper.select:
SELECT cfp.id, cfp.code, cfp.name, cfp.period_type AS periodType, cfp.dict_platform AS dictPlatform, cfp.dict_platform_name AS dictPlatformName, cfp.folder_type AS folderType, cff.id AS detailId, cff.business_type AS businessType, cff.type AS type, cff.file_keyword AS fileKeyword, cfp.disabled, cfp.remark, cfp.create_user_id AS createUserId, cfp.create_user_name AS createUserName, cfp.create_time AS createTime, cfp.update_user_id AS updateUserId, cfp.update_user_name AS updateUserName, cfp.update_time AS updateTime FROM cfg_file_parse cfp LEFT JOIN cfg_file_parse_file cff ON cff.main_id = cfp.id AND cff.is_deleted = FALSE WHERE cfp.is_deleted = FALSE
${params.permissionSql}
AND ${params.sqlMap.default}
ORDER BY
${item.field} ${item.sort}
cfp.create_time DESC, cff.sort ASC

SELECT cfp.id, cfp.code, cfp.name, cfp.period_type AS periodType, cfp.dict_platform AS dictPlatform, cfp.dict_platform_name AS dictPlatformName, cfp.folder_type AS folderType, cff.business_type AS businessType, cff.type AS type, cff.file_keyword AS fileKeyword, cfp.disabled, cfp.remark, cfp.create_user_id AS createUserId, cfp.create_user_name AS createUserName, cfp.create_time AS createTime, cfp.update_user_id AS updateUserId, cfp.update_user_name AS updateUserName, cfp.update_time AS updateTime FROM cfg_file_parse cfp LEFT JOIN cfg_file_parse_file cff ON cff.main_id = cfp.id AND cff.is_deleted = FALSE WHERE cfp.is_deleted = FALSE
${params.permissionSql}
AND ${params.sqlMap.default}
AND cfp.id IN
#{id}
ORDER BY
${item.field} ${item.sort}
cfp.create_time DESC, cff.sort ASC

SELECT CASE WHEN cfp.disabled THEN 'disabled' ELSE 'enabled' END AS tabFlag, CASE WHEN cfp.disabled THEN '停用' ELSE '启用' END AS tabFlagName, COUNT(cfp.id) AS count FROM cfg_file_parse cfp WHERE cfp.is_deleted = FALSE
${params.permissionSql}
GROUP BY CASE WHEN cfp.disabled THEN 'disabled' ELSE 'enabled' END,CASE WHEN cfp.disabled THEN '停用' ELSE '启用' END
